<?php
session_start();
require 'db.php';
require_once 'schema_helpers.php';
if (!isset($_SESSION['user_id']) || !in_array($_SESSION['role'] ?? '', ['Admin', 'SuperAdmin', 'AssistantSuperAdmin', 'AssistantAdmin'], true)) { header('Location: login.php'); exit(); }
ensureRepairAutomationSchema($conn);
$result = $conn->query("SELECT tr.repair_id, tr.work_performed, tr.technician_notes, tr.updated_at, r.ebike_model, r.issue_description, r.amount, c.name AS customer_name, t.name AS technician_name, t.custom_id AS technician_id FROM technician_repair_reports tr INNER JOIN repairs r ON r.repair_id=tr.repair_id LEFT JOIN users c ON c.user_id=r.customer_id LEFT JOIN users t ON t.user_id=tr.technician_id WHERE r.repair_status='Completed' ORDER BY tr.updated_at DESC");
?>
